  "Forecast needed": { th: "ต้องใส่วันคาดว่าจะเสร็จ", jp: "完了見込み日が必要" },
  "Update due": { th: "ถึงเวลาอัปเดต", jp: "更新期限" },
  "PROJECT SCHEDULE": { th: "แผนงานโปรเจกต์", jp: "プロジェクト工程" },
  "Everything assigned to you, across every project. Update it here — the project schedule, the PM's view and the customer plan update with it.":
    { th: "ทุกงานที่มอบหมายให้คุณ จากทุกโปรเจกต์ อัพเดทที่นี่ที่เดียว — แผนหลัก มุมมองของ PM และแผนฝั่งลูกค้าจะอัพเดทตามทันที", jp: "全プロジェクトであなたに割り当てられた作業。ここで更新すれば工程表・PMビュー・顧客向け計画も同時に更新されます。" },
  "You update the tasks assigned to you. Dates and scope belong to the project manager — use Request more days when you need a change.":
    { th: "คุณอัพเดทเฉพาะงานของคุณ ส่วนวันที่และขอบเขตเป็นของ PM — ถ้าต้องการเวลาเพิ่มให้กดขอวันเพิ่ม", jp: "更新できるのは自分のタスクのみ。日程とスコープはPMの管轄です — 変更が必要なら日数追加を申請してください。" },
  "One plan for the customer and the team — members update their own rows and every view updates with them.":
    { th: "แผนเดียวใช้ทั้งกับลูกค้าและทีม — สมาชิกอัพเดทแถวของตัวเอง แล้วทุกมุมมองอัพเดทตาม", jp: "顧客とチームで一つの計画 — メンバーが自分の行を更新すれば全ビューが更新されます。" },
  "Plan window": { th: "ช่วงเวลาแผน", jp: "計画期間" },
  "Work days": { th: "วันทำงาน", jp: "稼働日" },
  "work days": { th: "วันทำงาน", jp: "稼働日" },
  "Baseline": { th: "เส้นฐาน", jp: "ベースライン" },
  "vs baseline": { th: "เทียบเส้นฐาน", jp: "ベースライン比" },
  "Not frozen yet": { th: "ยังไม่ล็อกแผน", jp: "未確定" },
  "Freeze baseline": { th: "ล็อกเส้นฐาน", jp: "ベースライン確定" },
  "Re-baseline": { th: "ล็อกเส้นฐานใหม่", jp: "ベースライン再設定" },
  "Freeze": { th: "ล็อก", jp: "確定" },
  "Export customer plan": { th: "ส่งออกแผนฝั่งลูกค้า", jp: "顧客向け計画を出力" },
  "Customer plan exported — Customer rows only, baseline dates, no internal detail":
    { th: "ส่งออกแผนฝั่งลูกค้าแล้ว — เฉพาะแถว Customer วันที่ตามเส้นฐาน ไม่มีรายละเอียดภายใน", jp: "顧客向け計画を出力しました — Customer行のみ、ベースライン日付、内部詳細なし" },
  "requests for more days from the team are waiting for a decision":
    { th: "คำขอวันเพิ่มจากทีมกำลังรอการตัดสินใจ", jp: "件の日数追加申請が承認待ちです" },
  "Review": { th: "ตรวจดู", jp: "確認" },
  "Read only — the plan is maintained by": { th: "อ่านอย่างเดียว — แผนนี้ดูแลโดย", jp: "閲覧のみ — この計画の管理者:" },
  "Update your own tasks in My Work.": { th: "อัพเดทงานของคุณได้ที่หน้างานของฉัน", jp: "自分のタスクはマイワークで更新してください。" },
