  "Start from the team's standard phase template, or add phases one by one — the moment the PO arrives.":
    { th: "เริ่มจากเทมเพลตเฟสมาตรฐานของทีม หรือเพิ่มทีละเฟส — ทำได้ทันทีที่ได้รับ PO", jp: "チーム標準のフェーズテンプレートから、またはフェーズを一つずつ — POが届いたその日に。" },
  "Apply template": { th: "ใช้เทมเพลต", jp: "テンプレート適用" },
  "Template applied — adjust the dates and assign the PIC":
    { th: "ใช้เทมเพลตแล้ว — ปรับวันที่และมอบหมายผู้รับผิดชอบต่อ", jp: "テンプレートを適用しました — 日付調整とPIC割当を行ってください" },
  "The team's standard phase structure, ready the day the PO lands — adjust dates and assign owners after.":
    { th: "โครงสร้างเฟสมาตรฐานของทีม พร้อมใช้วันที่ PO มาถึง — ค่อยปรับวันที่และมอบหมายทีหลัง", jp: "チーム標準のフェーズ構成。PO到着日から使えます — 日付と担当は後から調整。" },
