  "Requests for more days": { th: "คำขอวันเพิ่ม", jp: "日数追加の申請" },
  "waiting for a decision": { th: "รอการตัดสินใจ", jp: "件が承認待ち" },
  "Accepting moves this task's end to": { th: "ถ้ายอมรับ งานนี้จะเสร็จวันที่", jp: "承認するとこのタスクの完了日は" },
