  "Rejected — the owner keeps the original dates":
    { th: "ปฏิเสธแล้ว — เจ้าของงานใช้กำหนดเดิม", jp: "却下しました — 担当者は元の日程のままです" },
  "Waiting for": { th: "รอ", jp: "待ち:" },
  "No open request — nobody is waiting on the PM.": { th: "ไม่มีคำขอค้าง — ไม่มีใครรอ PM อยู่", jp: "未処理の申請はありません。" },
