  "last update": { th: "อัพเดทล่าสุด", jp: "最終更新" },
  "Update feed": { th: "ฟีดการอัพเดท", jp: "更新フィード" },
  "Every change, from every member, in one place — the Monday meeting agenda":
    { th: "ทุกการเปลี่ยนแปลงจากทุกคนรวมอยู่ที่เดียว — ใช้เป็นวาระประชุมวันจันทร์ได้เลย", jp: "全メンバーの全変更を一箇所に — 月曜会議のアジェンダ" },
  "Requested": { th: "ขอ", jp: "申請:" },
  "waiting": { th: "รอ", jp: "待機中" },
  "Added": { th: "เพิ่ม", jp: "追加:" },
  "No update yet.": { th: "ยังไม่มีการอัพเดท", jp: "更新はまだありません。" },
