  "promised finish": { th: "กำหนดส่งที่สัญญาไว้", jp: "約束完了日" },
  "Variance against the baseline": { th: "ส่วนต่างเทียบเส้นฐาน", jp: "ベースラインとの差異" },
  "Signed work days — the rows dragging the delivery date are on top":
    { th: "หน่วยเป็นวันทำงาน — แถวที่ฉุดกำหนดส่งอยู่บนสุด", jp: "符号付き稼働日 — 納期を圧迫する行が上位" },
  "Baseline end": { th: "เสร็จตามเส้นฐาน", jp: "ベースライン完了" },
