  "Needs update": { th: "ต้องอัพเดท", jp: "要更新" },
  "Due this week": { th: "ครบกำหนดสัปดาห์นี้", jp: "今週期限" },
  "Awaiting the PM": { th: "รอ PM", jp: "PM待ち" },
  "requests sent": { th: "คำขอที่ส่งไป", jp: "件申請済" },
  "nothing pending": { th: "ไม่มีค้าง", jp: "保留なし" },
  "My tasks": { th: "งานของฉัน", jp: "マイタスク" },
  "My updates": { th: "การอัพเดทของฉัน", jp: "自分の更新" },
  "Needs your update": { th: "รอคุณอัพเดท", jp: "あなたの更新待ち" },
  "Late, blocked or quiet for too long — clear these first":
    { th: "ล่าช้า ติดปัญหา หรือเงียบนานเกินไป — เคลียร์พวกนี้ก่อน", jp: "遅延・ブロック・長期未更新 — まずこれらを片付けて" },
  "Nothing assigned to you yet": { th: "ยังไม่มีงานที่มอบหมายให้คุณ", jp: "割り当てられたタスクはまだありません" },
  "When the project manager assigns you a task it appears here.":
    { th: "เมื่อ PM มอบหมายงาน งานจะปรากฏที่นี่", jp: "PMがタスクを割り当てるとここに表示されます。" },
  "What you reported, in order": { th: "สิ่งที่คุณรายงาน เรียงตามเวลา", jp: "報告履歴 (時系列)" },
  "No update for 5 days": { th: "ไม่อัพเดทมา 5 วัน", jp: "5日間更新なし" },
  "This was due": { th: "งานนี้ครบกำหนด", jp: "期限:" },
  "set the forecast date so the plan tells the truth.":
    { th: "ใส่วันที่คาดว่าจะเสร็จ เพื่อให้แผนบอกความจริง", jp: "見込日を入れて計画を正直に保ちましょう。" },
  "Percent done": { th: "เปอร์เซ็นต์ความคืบหน้า", jp: "進捗率" },
