  /* ------------------------------------------------------------------------
     Sales Intake & Engineer Site Visit

     Terminology decisions worth recording, because they are the ones a Thai
     engineer will read on a phone at a customer's gate:
       * "Site visit" is ออกหน้างาน / เข้าหน้างาน, not the literal เยี่ยมชมสถานที่.
       * "Readiness" is ความพร้อมของข้อมูล — readiness *of the information*,
         since the score measures the record, not the customer.
       * "Check in / Check out" stay เช็คอิน / เช็คเอาต์: the team already says
         them in English, and translating them would be less clear, not more.
       * Japanese follows the manufacturing register the rest of the product
         uses — 現地調査 for a survey visit, 是正 for a revision request.
     ------------------------------------------------------------------------ */

  /* Navigation and workspace */
  "Sales Intake": { th: "รับความต้องการจากลูกค้า", jp: "営業インテーク" },
  "Site Visit": { th: "การเข้าหน้างาน", jp: "現地訪問" },
