  "This is the /demo prototype on sample data. The production workspace is the API-backed one.": { th: "หน้านี้เป็นต้นแบบ /demo ที่ใช้ข้อมูลตัวอย่าง ส่วนพื้นที่ทำงานจริงเชื่อมต่อผ่าน API", jp: "この画面はサンプルデータを使用する /demo プロトタイプです。本番ワークスペースは API に接続されています。" },
  "assignments": { th: "งานที่ได้รับมอบหมาย", jp: "件の割当" },

