  "ไม่มีสิทธิ์ดูแผนงาน": { th: "ไม่มีสิทธิ์ดูแผนงาน", en: "Work plan access required", jp: "作業計画へのアクセス権が必要です" },
  "ต้องมีสิทธิ์ schedule.read เพื่อดูและตอบรับงาน": { th: "ต้องมีสิทธิ์ schedule.read เพื่อดูและตอบรับงาน", en: "You need schedule.read permission to view and accept work.", jp: "作業の表示と受諾には schedule.read 権限が必要です。" },
  "Project Punchlist": { th: "รายการแก้ไขโปรเจกต์", jp: "プロジェクト指摘事項" },
  "บันทึก Issue ลูกค้า → อนุมัติงาน → สมาชิกตอบรับ → ลงมือทำ → ตรวจรับและปิด Issue": { th: "บันทึก Issue ลูกค้า → อนุมัติงาน → สมาชิกตอบรับ → ลงมือทำ → ตรวจรับและปิด Issue", en: "Record customer issue → approve work → member accepts → execute → verify and close", jp: "顧客課題を記録 → 作業承認 → 担当者受諾 → 実施 → 検収・完了" },
  "สร้างงานจาก Inquiry หรือ Project · ตรวจภาระงานก่อนอนุมัติ · ติดตามการตอบรับและความคืบหน้า": { th: "สร้างงานจาก Inquiry หรือ Project · ตรวจภาระงานก่อนอนุมัติ · ติดตามการตอบรับและความคืบหน้า", en: "Create work from an Inquiry or Project · review workload before approval · track acceptance and progress", jp: "引合またはプロジェクトから作業を作成し、承認前の負荷と受諾・進捗を追跡します" },
  "เพิ่ม Issue ลูกค้า": { th: "เพิ่ม Issue ลูกค้า", en: "Add customer issue", jp: "顧客課題を追加" },
