  "งานนี้ทำให้มีสัปดาห์เกินกำลัง กรุณาปรับคน/วัน หรือระบุเหตุผลก่อนอนุมัติ": { th: "งานนี้ทำให้มีสัปดาห์เกินกำลัง กรุณาปรับคน/วัน หรือระบุเหตุผลก่อนอนุมัติ", en: "This work overloads one or more weeks. Adjust man-days or give a reason before approval.", jp: "この作業により週次負荷が超過します。承認前に人日を調整するか理由を記録してください。" },
