  "Rate demonstrated impact and add a specific example where it helps.": { th: "ให้คะแนนผลกระทบที่แสดงให้เห็น และเพิ่มตัวอย่างที่ชัดเจนเมื่อช่วยอธิบายได้", jp: "実証された成果を評価し、必要に応じて具体例を記入してください。" },
  "Weighted score updates as you rate each area.": { th: "คะแนนถ่วงน้ำหนักจะอัปเดตเมื่อให้คะแนนแต่ละด้าน", jp: "各領域を評価すると加重スコアが更新されます。" },
