  "Link the rating to an Inquiry, customer meeting, estimate outcome or Project handover…": { th: "เชื่อมโยงคะแนนกับ Inquiry, Meeting ลูกค้า, ผลของ Estimate หรือการส่งต่องานเข้า Project…", jp: "評価を引合・顧客会議・見積結果・プロジェクト引継ぎに結び付けてください…" },
