const normalizeLabel = (text: string) => text.trim().replace(/\s+/g, " ").replace(/\s*\*$/, "").toLocaleLowerCase("en");
const labelAliases = new Map<string, { key: string; entry: Entry }>();
for (const [key, entry] of Object.entries(DICTIONARY)) {
  for (const alias of [key, entry.en, entry.th, entry.jp]) {
    if (alias && !labelAliases.has(normalizeLabel(alias))) labelAliases.set(normalizeLabel(alias), { key, entry });
  }
}
export function translate(text: string, lang: Lang) {
  const exact = DICTIONARY[text];
  const match = exact ? { key: text, entry: exact } : labelAliases.get(normalizeLabel(text));
  if (!match) return text;
  const { key, entry } = match;
  const value = lang === "TH" ? entry.th : lang === "JP" ? entry.jp : entry.en ?? key;
  return !exact && /\*\s*$/.test(text) && !/\*\s*$/.test(value) ? `${value} *` : value;
}

export type Translator = (text: string) => string;

export const LanguageContext = createContext<{ lang: Lang; setLang: (lang: Lang) => void; t: Translator }>({
  lang: "EN",
  setLang: () => undefined,
  t: (text) => text,
});

export const useLanguage = () => useContext(LanguageContext);

export const localeFor = (lang: Lang) => lang === "TH" ? "th-TH" : lang === "JP" ? "ja-JP" : "en-GB";

/** Set before React state: date helpers must see the new language in that same render. */
export function applyDocumentLanguage(lang: Lang) {
  if (typeof document !== "undefined") document.documentElement.lang = lang === "TH" ? "th" : lang === "JP" ? "ja" : "en";
}

export const currentLocale = () => {
  if (typeof document === "undefined") return "en-GB";
  return document.documentElement.lang === "th" ? "th-TH" : document.documentElement.lang === "ja" ? "ja-JP" : "en-GB";
};

/** Shorthand for screens: const t = useT(); … t("Save") */
export const useT = (): Translator => useContext(LanguageContext).t;
